function simplifyPath(path) {
  const stack = [] //@init
  for (const part of path.split('/')) { //@loop
    if (part === '' || part === '.') continue //@skip
    if (part === '..') { if (stack.length) stack.pop(); continue } //@pop
    stack.push(part) //@push
  }
  return '/' + stack.join('/') //@done
}

